import artifact from '@localize-infra/eval/benchmarks.json';

/**
 * The published benchmark numbers.
 *
 * Imported from the artifact generated by `@localize-infra/eval`, never typed
 * in by hand. A test in that package asserts the committed artifact matches
 * what the generator produces from the committed corpus, so a number on this
 * site cannot drift from the data it claims to come from.
 *
 * Regenerate with:
 *   npm run benchmarks:build -w @localize-infra/eval
 */
export const BENCHMARKS = artifact;

export type Check = { applicable: number; passed: number };

/**
 * A check with nothing to check is not a pass.
 *
 * Rendering "100%" off a zero denominator is the single easiest way for a
 * benchmarks page to lie without containing a false statement, so the empty
 * case is a distinct variant that callers cannot accidentally format as a
 * percentage.
 */
export type Rate =
  | { kind: 'measured'; percent: number; passed: number; applicable: number }
  | { kind: 'not-applicable' };

export function rate(check: Check): Rate {
  if (check.applicable === 0) return { kind: 'not-applicable' };
  return {
    kind: 'measured',
    percent: (check.passed / check.applicable) * 100,
    passed: check.passed,
    applicable: check.applicable,
  };
}

/** One decimal place, but no trailing ".0" — "100%" reads better than "100.0%". */
export function formatPercent(percent: number): string {
  const rounded = Math.round(percent * 10) / 10;
  return `${Number.isInteger(rounded) ? rounded : rounded.toFixed(1)}%`;
}

export function conditionBy(condition: 'A' | 'B') {
  const found = BENCHMARKS.conditions.find((c) => c.condition === condition);
  if (!found) {
    // Unreachable against the generated artifact, and a build-time crash is the
    // right outcome if the artifact shape ever changes underneath the page.
    throw new Error(`Benchmark artifact is missing condition ${condition}`);
  }
  return found;
}

export const LOCALE_NAMES: Record<string, string> = {
  de: 'German',
  ja: 'Japanese',
  es: 'Spanish',
  ar: 'Arabic',
  'pt-BR': 'Portuguese (Brazil)',
};

export function localeName(locale: string): string {
  return LOCALE_NAMES[locale] ?? locale;
}
